const j = $input.first().json;
const raw = String(j.chatInput ?? '');
const text = raw.slice(0, 6000);
const risk = /hair\s*loss|alopecia|scalp|allerg|rash|infection|refund|complaint|compensation|negotia|cheaper|too expensive|way too much|can you do .{0,24}off|give me .{0,24}off|lower the price|price match|match .{0,16}price|脱发|头皮|过敏|退款|投诉|赔偿|议价|便宜点|太贵|贵了|打个折|降价|能不能.{0,6}(便宜|优惠|折)/i.test(text);
return [{ json: {
  chatInput: text,
  truncated: raw.length > 6000,
  sessionId: String(j.sessionId ?? 'internal-test'),
  language: /[㐀-鿿]/.test(text) ? 'zh' : 'en',
  forceEscalate: risk,
  identityVerified: false,
  customerId: null,
  channel: 'internal_test',
  shadowMode: true
} }];

// Loads the per-session slot state written by the previous turn and turns it
// into (a) structured state for the renderer and (b) a prompt block for the
// model. This node replaces the removed "Six turn memory": everything the model
// learns about earlier turns now comes from verified slots, never from raw
// prior tool observations.
const ctx = $('Normalize and screen input').first().json;
const zh = ctx.language === 'zh';

// ---------------------------------------------------------------------------
// Canonical slot definitions. Injected verbatim into BOTH the "Conversation
// state" node and the "Validate" node at build time (placeholder __SLOT_RULES__)
// so the two can never disagree about what is missing or what to ask next.
// ---------------------------------------------------------------------------

// Order is the real salon booking order: what → which look → when (range) →
// who → which exact slot. A slot can only be asked for once everything it
// depends on is known, so this doubles as the priority list.
const SLOT_ORDER = ['service', 'style', 'time_window', 'stylist', 'time_slot'];

// Style only matters for cut/colour work. A blow dry or a bond treatment needs
// no taxonomy entry, and asking for one would be a dead end.
const STYLE_IRRELEVANT_SERVICES = ['svc_treat_olaplex', 'svc_blowdry', 'svc_treat_keratin'];

function slotFilled(slots, key) {
  const s = slots || {};
  if (key === 'service')     return !!(s.service && s.service.id);
  if (key === 'style')       return !!(s.style && s.style.taxonomy_id);
  if (key === 'time_window') return !!(s.time && s.time.window_from);
  if (key === 'stylist')     return !!(s.stylist && (s.stylist.id || s.stylist.any === true));
  if (key === 'time_slot')   return !!(s.time && s.time.chosen_slot && s.time.chosen_slot.start);
  return false;
}

function slotApplicable(slots, key) {
  const s = slots || {};
  if (key !== 'style') return true;
  // unknown service yet -> assume style will be needed, so it keeps its priority
  if (!(s.service && s.service.id)) return true;
  return STYLE_IRRELEVANT_SERVICES.indexOf(s.service.id) === -1;
}

function missingSlots(slots) {
  const out = [];
  for (const k of SLOT_ORDER) if (slotApplicable(slots, k) && !slotFilled(slots, k)) out.push(k);
  return out;
}

// Adaptive questioning: >=3 gaps -> ask only the highest-priority one; 1-2 gaps
// -> ask them together. time_slot is never "asked" in the abstract, it is
// answered by presenting real slots, so it is always handled on its own.
function slotsToAsk(missing) {
  if (!missing.length) return [];
  if (missing[0] === 'time_slot') return ['time_slot'];
  const askable = missing.filter(k => k !== 'time_slot');
  if (!askable.length) return ['time_slot'];
  return askable.length >= 3 ? [askable[0]] : askable;
}

const SLOT_LABEL = {
  service:     { zh: '服务项目', en: 'service' },
  style:       { zh: '发型',     en: 'hairstyle' },
  time_window: { zh: '方便的时间段', en: 'when you are free' },
  stylist:     { zh: '发型师',   en: 'stylist' },
  time_slot:   { zh: '具体时段', en: 'a specific time' }
};

// One short line per confirmed slot, used in both the model prompt and the
// customer-facing progress block.
function slotLines(slots, zh) {
  const s = slots || {}, out = [];
  if (slotFilled(s, 'service')) {
    const v = s.service;
    out.push((zh ? '服务：' : 'Service: ') + (zh ? (v.name_zh || v.name) : v.name) +
      (Number.isFinite(Number(v.price)) ? ' — ' + (v.currency || 'AUD') + ' ' + Number(v.price).toFixed(2) : '') +
      (Number.isFinite(Number(v.duration_min)) ? ' / ' + Number(v.duration_min) + (zh ? ' 分钟' : ' min') : ''));
  }
  if (slotFilled(s, 'style')) {
    const v = s.style;
    out.push((zh ? '发型：' : 'Style: ') + (zh ? (v.name_zh || v.name_en) : (v.name_en || v.name_zh)));
  }
  if (slotFilled(s, 'stylist')) {
    out.push((zh ? '发型师：' : 'Stylist: ') + (s.stylist.any === true ? (zh ? '都可以' : 'no preference') : s.stylist.name));
  }
  if (slotFilled(s, 'time_slot')) {
    out.push((zh ? '时间：' : 'Time: ') + s.time.chosen_slot.label);
  } else if (slotFilled(s, 'time_window')) {
    out.push((zh ? '时间范围：' : 'When: ') + s.time.window_label);
  }
  return out;
}


const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// The Data Table `get` is filtered by session_id, but be defensive: never adopt
// another session's row.
const row = degraded ? null : items.find(r => r && r.session_id === ctx.sessionId) || null;

const TTL_MS = 24 * 60 * 60 * 1000;
const parse = (v, fallback) => { try { const o = JSON.parse(v); return o && typeof o === 'object' ? o : fallback; } catch { return fallback; } };

let slots = {}, recentTurns = [], lastQuestion = '', turnCount = 0, status = 'gathering', stale = false;
if (row) {
  const age = Date.now() - Date.parse(row.updated_at || row.updatedAt || 0);
  stale = Number.isFinite(age) && age > TTL_MS;
  if (!stale) {
    slots = parse(row.slots, {});
    recentTurns = Array.isArray(parse(row.recent_turns, [])) ? parse(row.recent_turns, []) : [];
    lastQuestion = String(row.last_question || '');
    turnCount = Number(row.turn_count) || 0;
    status = String(row.status || 'gathering');
  }
}
// A customer can always start over.
const resetRequested = /^\s*(reset|restart|start over|重来|重新开始|取消重来)\s*$/i.test(String(ctx.chatInput || ''));
if (resetRequested) { slots = {}; recentTurns = []; lastQuestion = ''; turnCount = 0; status = 'gathering'; }

const missing = missingSlots(slots);
const known = slotLines(slots, zh);

// The prompt the agent actually receives. Static rules live in the system
// message; everything session-specific is assembled here so it is auditable.
const promptParts = [];
if (known.length) {
  promptParts.push((zh ? '【已确认的信息 — 不要重复询问，也不要重新验证】' : '[ALREADY CONFIRMED - do not ask again, do not re-verify]'));
  for (const l of known) promptParts.push('- ' + l);
  const ids = [];
  if (slots.service && slots.service.id) ids.push('service_id=' + slots.service.id);
  if (slots.style && slots.style.taxonomy_id) ids.push('taxonomy_id=' + slots.style.taxonomy_id);
  if (slots.stylist && slots.stylist.id) ids.push('stylist_id=' + slots.stylist.id);
  if (ids.length) promptParts.push((zh ? '已确认的 ID（可直接在输出中使用）：' : 'Confirmed IDs (safe to use in your output): ') + ids.join(', '));
}
if (missing.length) {
  promptParts.push((zh ? '【还缺】' : '[STILL MISSING]') + ' ' + missing.map(k => SLOT_LABEL[k] ? SLOT_LABEL[k][zh ? 'zh' : 'en'] : k).join(zh ? '、' : ', '));
}
if (lastQuestion) {
  promptParts.push((zh ? '【上一轮我们问的是】' : '[WE ASKED LAST TURN]') + ' ' + lastQuestion +
    (zh ? ' — 顾客这一轮多半是在回答它。' : ' - the customer is most likely answering it now.'));
}
if (recentTurns.length) {
  promptParts.push(zh ? '【顾客最近几轮的原话】' : '[RECENT CUSTOMER MESSAGES]');
  recentTurns.slice(-3).forEach((t, i) => promptParts.push((i + 1) + '. ' + t));
}
// The model has no clock. Without this it cannot resolve "this Wednesday".
const TZ = 'Australia/Sydney';
const todayLabel = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, weekday: 'long', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
promptParts.push((zh ? '【今天】' : '[TODAY]') + ' ' + todayLabel + ' (' + TZ + ')');
promptParts.push((zh ? '【顾客本轮说】' : '[CUSTOMER SAYS NOW]') + '\n' + String(ctx.chatInput || ''));

return [{ json: {
  ...ctx,
  slots,
  slotsMissing: missing,
  knownLines: known,
  status,
  lastQuestion,
  recentTurns,
  turnCount,
  convDegraded: degraded,
  stateStale: stale,
  resetRequested,
  stateRowExists: !!row,
  agentPrompt: promptParts.join('\n')
} }];

// Risk-flagged requests never reach the model. They still have to preserve the
// conversation so the customer can carry on afterwards, so the slot bag is
// passed through untouched rather than reset.
const conv = $('Conversation state').first().json;
const zh = conv.language === 'zh';
const medical = /hair\s*loss|alopecia|scalp|allerg|rash|infection|脱发|头皮|过敏/i.test(String(conv.chatInput ?? ''));
const reply = medical
  ? (zh ? '这个涉及头皮健康，我不方便给建议。我已经转给店里的同事，也建议你找专业人士看一下。'
        : "That's a scalp-health question and not something I should advise on. I've passed it to a colleague, and it's worth seeing a professional too.")
  : (zh ? '这个我帮你转给店里的同事处理，他们会尽快联系你。'
        : "I've passed this to a colleague at the salon — they'll be in touch shortly.");

const prior = (conv.slots && typeof conv.slots === 'object') ? conv.slots : {};
const recent = (Array.isArray(conv.recentTurns) ? conv.recentTurns : []).concat([String(conv.chatInput || '')]).slice(-3);
const turn = (Number(conv.turnCount) || 0) + 1;

return [{ json: {
  session_id: conv.sessionId,
  request_text: conv.chatInput,
  draft_reply: reply,
  reason: medical ? 'health_topic' : 'complaint_or_bargaining',
  status: 'pending_human',
  guardrail_pass: true,
  errors: [],
  requires_human: true,
  auto_sent: false,
  tool_calls: [],
  not_configured_tools: [],
  truncated: !!conv.truncated,
  // slots survive the detour
  slots_next: prior,
  slots_json: JSON.stringify(prior),
  recent_turns_json: JSON.stringify(recent),
  last_question: String(conv.lastQuestion || ''),
  conv_status: 'escalated',
  turn_count: turn,
  missing: Array.isArray(conv.slotsMissing) ? conv.slotsMissing : [],
  proposals: [],
  ready: false,
  metrics: { guardrail_pass: 1, errors_count: 0, hallucination_blocked: 0, tool_call_count: 0,
    escalated: 1, agent_failed: 0, tool_failures: 0, not_configured_hit: 0,
    slots_filled: 5 - (Array.isArray(conv.slotsMissing) ? conv.slotsMissing.length : 5), turn: turn, ready: 0 },
  output: reply
} }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.service_id);
return [{ json: { ...ctx, rows, degraded } }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.promotion_id);
return [{ json: { ...ctx, rows, degraded } }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.stylist_id);
return [{ json: { ...ctx, rows, degraded } }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.taxonomy_id);
return [{ json: { ...ctx, rows, degraded } }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.stylist_id);
return [{ json: { ...ctx, rows, degraded } }];

// FIX P0-2: degrade instead of throw. The upstream Data Table node now has
// onError=continueRegularOutput, so a backend failure arrives as {error:...}
// instead of crashing the whole execution.
const items = $input.all().map(i => i.json);
const degraded = items.some(r => r && r.error);
// Conversation state re-exports the normalized ctx plus the slot bag, so every
// snapshot carries both and tools can read either from one place.
const ctx = $('Conversation state').first().json;
const rows = degraded ? [] : items.filter(r => r && r.appointment_id);
return [{ json: { ...ctx, rows, degraded } }];

let q = {};
try { q = typeof query === 'string' ? JSON.parse(query || '{}') : (query ?? {}); }
catch { return JSON.stringify({ ok: false, tool: 'service_catalog', error: 'invalid_input' }); }
const conv = $('Conversation state').first().json;
if (conv.forceEscalate) return JSON.stringify({ ok: false, tool: 'service_catalog', error: 'human_required' });
const snap = $('Services snapshot').first().json;
if (snap.degraded) return JSON.stringify({ ok: false, tool: 'service_catalog', error: 'catalog_unavailable', retryable: true });

function containsTerm(hay, term) {
  const t = String(term ?? '').trim().toLowerCase(), h = String(hay ?? '').toLowerCase();
  if (!t || !h) return false;
  if (/[\u3400-\u9fff]/.test(t) || /[\u3400-\u9fff]/.test(h)) return h.includes(t);
  const esc = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9])' + esc + '($|[^a-z0-9])').test(h);
}
const active = snap.rows.filter(r => r.active === true && Number.isFinite(Number(r.price)) && Number(r.price) >= 0 && r.currency);
function resolveService(text) {
  const qy = String(text ?? '').trim().toLowerCase();
  if (!qy) return null;
  const scored = active.map(r => {
    let best = 0;
    for (const t of [r.service_id, r.name, r.name_zh].map(x => String(x ?? '').trim()).filter(Boolean)) {
      if (containsTerm(qy, t)) best = Math.max(best, t.length);
      else if (containsTerm(t, qy)) best = Math.max(best, qy.length / 2);
    }
    return { r, best };
  }).filter(x => x.best > 0).sort((a, b) => b.best - a.best || String(a.r.service_id).localeCompare(String(b.r.service_id)));
  if (!scored.length) return null;
  if (scored.length > 1 && scored[0].best === scored[1].best) return null;
  return scored[0].r;
}

// The customer's own words are the authority. Only if they match nothing do we
// fall back to the model's paraphrase, and then the result is flagged so it
// cannot silently enter the slot state (live run: "shorter and fresher" was
// rewritten into a query that matched an unrelated service).
const explicitId = String(q.service_id ?? '').trim();
const knownId = !!explicitId && active.some(r => r.service_id === explicitId);
let resolved = null, resolvedFrom = null;
if (!knownId) {
  resolved = resolveService(conv.chatInput);
  if (resolved) resolvedFrom = 'customer_text';
  else { resolved = resolveService(q.service_query); if (resolved) resolvedFrom = 'model_paraphrase'; }
}
const wanted = knownId ? explicitId : (resolved ? resolved.service_id : '');
const rows = wanted ? active.filter(r => r.service_id === wanted) : active;
return JSON.stringify({
  ok: true, tool: 'service_catalog',
  filtered_by_service_id: wanted || null,
  unknown_service_id: !!(explicitId && !knownId),
  resolved_from: resolvedFrom,
  services: rows,
  ...(String(q.service_query ?? '').trim() && !resolved ? { result: 'NO_MATCHING_SERVICE', final_instruction: 'No service matches "' + String(q.service_query).replace(/[\r\n"\\]/g, ' ').trim().slice(0, 40) + '". The complete catalogue is listed above; if none of it is what the customer asked for, the salon does not offer that service. Do NOT call any other tool. Answer now with intent=catalog and service_ids=[] (or the matching id from the list), escalate=false.' } : {})
});

let q = {};
try { q = typeof query === 'string' ? JSON.parse(query || '{}') : (query ?? {}); }
catch { return JSON.stringify({ ok: false, tool: 'get_promotions', error: 'invalid_input' }); }
const conv = $('Conversation state').first().json;
if (conv.forceEscalate) return JSON.stringify({ ok: false, tool: 'get_promotions', error: 'human_required' });
const snap = $('Promotions snapshot').first().json;
if (snap.degraded) return JSON.stringify({ ok: false, tool: 'get_promotions', error: 'catalog_unavailable', retryable: true });

function containsTerm(hay, term) {
  const t = String(term ?? '').trim().toLowerCase(), h = String(hay ?? '').toLowerCase();
  if (!t || !h) return false;
  if (/[㐀-鿿]/.test(t) || /[㐀-鿿]/.test(h)) return h.includes(t);
  const esc = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp('(^|[^a-z0-9])' + esc + '($|[^a-z0-9])').test(h);
}
const serviceRows = ($('Services snapshot').first().json.rows || []).filter(r => r.active === true);
function resolveService(text) {
  const qy = String(text ?? '').trim().toLowerCase();
  if (!qy) return null;
  const scored = serviceRows.map(r => {
    let best = 0;
    for (const t of [r.service_id, r.name, r.name_zh].map(x => String(x ?? '').trim()).filter(Boolean)) {
      if (containsTerm(qy, t)) best = Math.max(best, t.length);
      else if (containsTerm(t, qy)) best = Math.max(best, qy.length / 2);
    }
    return { r, best };
  }).filter(x => x.best > 0).sort((a, b) => b.best - a.best || String(a.r.service_id).localeCompare(String(b.r.service_id)));
  if (!scored.length) return null;
  if (scored.length > 1 && scored[0].best === scored[1].best) return null;
  const r = scored[0].r;
  return { service_id: r.service_id, name: r.name, name_zh: r.name_zh, price: r.price, currency: r.currency, duration_min: r.duration_min };
}

// Priority: an id a tool already verified > the confirmed slot > the customer's
// own words > the model's paraphrase (flagged, cannot enter slot state).
const explicitId = String(q.service_id ?? '').trim();
const knownId = !!explicitId && serviceRows.some(r => r.service_id === explicitId);
const slotSvcId = conv.slots && conv.slots.service && conv.slots.service.id;
let resolved = null, resolvedFrom = null;
if (!knownId) {
  if (slotSvcId && serviceRows.some(r => r.service_id === slotSvcId)) {
    const r = serviceRows.find(x => x.service_id === slotSvcId);
    resolved = { service_id: r.service_id, name: r.name, name_zh: r.name_zh, price: r.price, currency: r.currency, duration_min: r.duration_min };
    resolvedFrom = 'confirmed_slot';
  } else {
    resolved = resolveService(conv.chatInput);
    if (resolved) resolvedFrom = 'customer_text';
    else { resolved = resolveService(q.service_query); if (resolved) resolvedFrom = 'model_paraphrase'; }
  }
}
const wanted = knownId ? explicitId : (resolved ? resolved.service_id : '');

// --- validity window in salon-local time ----------------------------------
const TZ = 'Australia/Sydney';
function tzOffsetMs(d) {
  const dtf = new Intl.DateTimeFormat('en-US', { timeZone: TZ, hour12: false,
    year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit' });
  const p = {};
  for (const part of dtf.formatToParts(d)) if (part.type !== 'literal') p[part.type] = part.value;
  const h = p.hour === '24' ? 0 : Number(p.hour);
  return Date.UTC(Number(p.year), Number(p.month) - 1, Number(p.day), h, Number(p.minute), Number(p.second)) - d.getTime();
}
function localBoundary(value, endOfDay) {
  const s = String(value ?? '').trim();
  if (!s) return null;
  // bare date, or a `date` column serialised as midnight UTC: both mean "that calendar day"
  const m = s.match(/^(\d{4})-(\d{2})-(\d{2})(?:T00:00:00(?:\.000)?Z)?$/);
  if (!m) { const t = Date.parse(s); return Number.isFinite(t) ? t : null; }
  const y = Number(m[1]), mo = Number(m[2]) - 1, d = Number(m[3]);
  const H = endOfDay ? 23 : 0, M = endOfDay ? 59 : 0, S = endOfDay ? 59 : 0, MS = endOfDay ? 999 : 0;
  let ts = Date.UTC(y, mo, d, H, M, S, MS);
  for (let i = 0; i < 2; i++) ts = Date.UTC(y, mo, d, H, M, S, MS) - tzOffsetMs(new Date(ts));
  return ts;
}

const now = Date.now();
const rows = snap.rows.filter(r => {
  try {
    if (r.active !== true) return false;
    const from = localBoundary(r.valid_from, false), to = localBoundary(r.valid_to, true);
    if (from === null || to === null) return false;
    if (now < from || now > to) return false;
    const channels = JSON.parse(r.channels || '[]');
    if (!(channels.includes('web') || channels.includes('all'))) return false;
    const e = JSON.parse(r.eligibility || '{}');
    // Anonymous internal prototype: only promos with no per-customer conditions
    // can be verified. Documented limitation, not a silent drop.
    if (e.everyone !== true) return false;
    if (!Object.keys(e).every(k => ['everyone', 'service_ids'].includes(k))) return false;
    if (e.service_ids && (!wanted || !e.service_ids.includes(wanted))) return false;
    return true;
  } catch { return false; }
});
return JSON.stringify({
  ok: true, tool: 'get_promotions',
  timezone: TZ,
  filtered_by_service_id: wanted || null,
  unknown_service_id: explicitId && !knownId ? explicitId : null,
  resolved_service: resolved,
  resolved_from: resolvedFrom,
  promotions: rows,
