  time_slot:   { zh: '具体时段', en: 'a specific time' }
};

// One short line per confirmed slot, used in both the model prompt and the
// customer-facing progress block.
function slotLines(slots, zh) {
  const s = slots || {}, out = [];
  if (slotFilled(s, 'service')) {
    const v = s.service;
    out.push((zh ? '服务：' : 'Service: ') + (zh ? (v.name_zh || v.name) : v.name) +
      (Number.isFinite(Number(v.price)) ? ' — ' + (v.currency || 'AUD') + ' ' + Number(v.price).toFixed(2) : '') +
      (Number.isFinite(Number(v.duration_min)) ? ' / ' + Number(v.duration_min) + (zh ? ' 分钟' : ' min') : ''));
  }
  if (slotFilled(s, 'style')) {
    const v = s.style;
    out.push((zh ? '发型：' : 'Style: ') + (zh ? (v.name_zh || v.name_en) : (v.name_en || v.name_zh)));
  }
  if (slotFilled(s, 'stylist')) {
    out.push((zh ? '发型师：' : 'Stylist: ') + (s.stylist.any === true ? (zh ? '都可以' : 'no preference') : s.stylist.name));
  }
  if (slotFilled(s, 'time_slot')) {
    out.push((zh ? '时间：' : 'Time: ') + s.time.chosen_slot.label);
  } else if (slotFilled(s, 'time_window')) {
    out.push((zh ? '时间范围：' : 'When: ') + s.time.window_label);
  }
  return out;
}


let p = raw.output;
try { if (typeof p === 'string') p = JSON.parse(p); } catch { p = null; }

// ---------------------------------------------------------------------------
// 1. Evidence from THIS turn's tool calls
// ---------------------------------------------------------------------------
const errors = [];
const notConfigured = [];
const toolFailures = [];
const toolCalls = [];
const evidence = { services: [], promotions: [], stylists: [], styles: [], slots: [] };
const paraphrased = { services: new Set(), styles: new Set() };
const steps = raw.intermediateSteps ?? [];

for (const st of steps) {
  if (st && st.action && st.action.tool) toolCalls.push(st.action.tool);
  let o = st ? st.observation : null;
  try {
    for (let d = 0; d < 6; d++) {
      if (typeof o === 'string') { o = JSON.parse(o); continue; }
      if (Array.isArray(o)) { o = o[0]; continue; }
      if (o && o.json) { o = o.json; continue; }
      if (o && o.response) { o = o.response; continue; }
      break;
    }
    if (!o) continue;
    if (o.ok !== true) {
      if (o.error === 'not_configured') notConfigured.push(o.tool);
      else if (['confirmation_required', 'human_required', 'invalid_input'].indexOf(o.error) === -1) toolFailures.push(o.tool + ':' + String(o.error ?? 'unknown'));
      continue;
    }
    if (o.tool === 'service_catalog') {
      evidence.services.push(...(o.services ?? []));
      if (o.resolved_from === 'model_paraphrase' && o.filtered_by_service_id) paraphrased.services.add(o.filtered_by_service_id);
    }
    if (o.tool === 'get_promotions') {
      evidence.promotions.push(...(o.promotions ?? []));
      if (o.resolved_service) {
        evidence.services.push(o.resolved_service);
        if (o.resolved_from === 'model_paraphrase') paraphrased.services.add(o.resolved_service.service_id);
      }
    }
    if (o.tool === 'match_stylist') {
      evidence.stylists.push(...(o.stylists ?? []));
      if (o.resolved_style) {
        evidence.styles.push(o.resolved_style);
        if (o.resolved_from === 'model_paraphrase') paraphrased.styles.add(o.resolved_style.taxonomy_id);
      }
    }
    if (o.tool === 'classify_style' && o.confidence >= 0.8 && o.taxonomy_id) {
      evidence.styles.push({ taxonomy_id: o.taxonomy_id, name_en: o.name_en, name_zh: o.name_zh });
      if (o.resolved_from === 'model_paraphrase') paraphrased.styles.add(o.taxonomy_id);
    }
    if (o.tool === 'find_slots') evidence.slots.push(...(o.slots ?? []));
  } catch (e) { /* unparseable observation contributes no evidence */ }
}

const uniq = (arr, key) => { const seen = new Set(); return arr.filter(r => { const k = r && r[key]; if (seen.has(k)) return false; seen.add(k); return true; }); };
evidence.services   = uniq(evidence.services, 'service_id');
evidence.promotions = uniq(evidence.promotions, 'promotion_id');
evidence.stylists   = uniq(evidence.stylists, 'stylist_id');
evidence.styles     = uniq(evidence.styles, 'taxonomy_id');
evidence.slots      = uniq(evidence.slots, 'start');

// ---------------------------------------------------------------------------
// 2. Evidence pool = this turn's evidence UNION previously verified slots.
//    This is what makes multi-turn possible without weakening the guardrail:
//    a prior-turn ID is acceptable because a tool verified it when it entered
//    the slot bag, not because the model asserts it now.
// ---------------------------------------------------------------------------
const prior = (conv.slots && typeof conv.slots === 'object') ? conv.slots : {};
const pool = {
  services:   evidence.services.slice(),
  promotions: evidence.promotions.slice(),
  stylists:   evidence.stylists.slice(),
  styles:     evidence.styles.slice(),
  slots:      evidence.slots.slice()
};
if (prior.service && prior.service.id && !pool.services.some(r => r.service_id === prior.service.id))
  pool.services.push({ service_id: prior.service.id, name: prior.service.name, name_zh: prior.service.name_zh,
    price: prior.service.price, currency: prior.service.currency, duration_min: prior.service.duration_min });
if (prior.style && prior.style.taxonomy_id && !pool.styles.some(r => r.taxonomy_id === prior.style.taxonomy_id))
  pool.styles.push({ taxonomy_id: prior.style.taxonomy_id, name_en: prior.style.name_en, name_zh: prior.style.name_zh });
if (prior.stylist && prior.stylist.id && !pool.stylists.some(r => r.stylist_id === prior.stylist.id))
  pool.stylists.push({ stylist_id: prior.stylist.id, name: prior.stylist.name, reasons: prior.stylist.reasons || [] });
if (prior.promotion && prior.promotion.id && !pool.promotions.some(r => r.promotion_id === prior.promotion.id))
  pool.promotions.push({ promotion_id: prior.promotion.id, title: prior.promotion.title, discount: prior.promotion.discount });
const priorOffered = (prior.time && Array.isArray(prior.time.offered)) ? prior.time.offered : [];
for (const s of priorOffered) if (!pool.slots.some(r => r.start === s.start)) pool.slots.push(s);

// ---------------------------------------------------------------------------
// 3. Guardrail: every ID the model emits must be in the pool
// ---------------------------------------------------------------------------
if (!p || typeof p !== 'object') errors.push('invalid_agent_output');
p = p ?? {};

for (const pair of [
  ['service_ids', 'services', 'service_id'],
  ['promotion_ids', 'promotions', 'promotion_id'],
  ['stylist_ids', 'stylists', 'stylist_id']
]) {
  const field = pair[0], key = pair[1], idKey = pair[2];
  if (!Array.isArray(p[field])) { errors.push('invalid_' + field); continue; }
  for (const v of p[field]) if (!pool[key].some(r => r[idKey] === v)) errors.push('unsupported_' + field);
}
if (p.taxonomy_id && !pool.styles.some(r => r.taxonomy_id === p.taxonomy_id)) errors.push('unsupported_taxonomy');
const chosenStart = String(p.chosen_slot_start ?? '').trim();
const chosenSlot = chosenStart ? pool.slots.find(s => s.start === chosenStart) : null;
if (chosenStart && !chosenSlot) errors.push('unsupported_slot');

// A required tool may be skipped when the slot bag already holds the answer.
const requiredTool = { catalog: 'service_catalog', promotions: 'get_promotions', style: 'classify_style', stylist: 'match_stylist' }[p.intent];
const satisfiedByPrior = { catalog: !!(prior.service && prior.service.id), promotions: !!(prior.promotion && prior.promotion.id),
  style: !!(prior.style && prior.style.taxonomy_id), stylist: !!(prior.stylist && prior.stylist.id) }[p.intent];
if (requiredTool && toolCalls.indexOf(requiredTool) === -1 && !satisfiedByPrior) errors.push('required_tool_not_called');
if (raw.error) errors.push('agent_failed');

// ---------------------------------------------------------------------------
// 4. Merge verified facts into the slot bag.
//    Business facts (service / style / stylist / slot / promotion / price) may
//    only enter from tool-verified evidence. Customer preferences (time window,
//    day part) are model-extracted and carry a source marker instead.
//    A single ID means the customer settled on one; a list means we were still
//    presenting options, so nothing is locked in.
// ---------------------------------------------------------------------------
const slots = JSON.parse(JSON.stringify(prior));
const blocked = errors.length > 0;
const proposals = [];

if (!blocked && Array.isArray(p.service_ids) && p.service_ids.length === 1) {
  const row = pool.services.find(r => r.service_id === p.service_ids[0]);
  if (row) {
    if (paraphrased.services.has(row.service_id)) proposals.push('service');
    else slots.service = { id: row.service_id, name: row.name, name_zh: row.name_zh, price: Number(row.price),
      currency: row.currency || 'AUD', duration_min: Number(row.duration_min), verified_turn: turn };
  }
}
if (!blocked && p.taxonomy_id) {
  const row = pool.styles.find(r => r.taxonomy_id === p.taxonomy_id);
  if (row) {
    if (paraphrased.styles.has(row.taxonomy_id)) proposals.push('style');
    else slots.style = { taxonomy_id: row.taxonomy_id, name_en: row.name_en, name_zh: row.name_zh, verified_turn: turn };
  }
}
if (!blocked && Array.isArray(p.stylist_ids) && p.stylist_ids.length === 1) {
  const row = pool.stylists.find(r => r.stylist_id === p.stylist_ids[0]);
  if (row) slots.stylist = { id: row.stylist_id, name: row.name, reasons: row.reasons || [], verified_turn: turn };
}
if (!blocked && p.stylist_no_preference === true && !(slots.stylist && slots.stylist.id))
  slots.stylist = { any: true, verified_turn: turn };

// time window: a customer preference, not a business fact
const win = String(p.time_window ?? '').trim();
const winMatch = win.match(/^(\d{4}-\d{2}-\d{2})(?:\s*(?:\.\.|to|~|-)\s*(\d{4}-\d{2}-\d{2}))?$/);
if (!blocked && winMatch) {
  const dayPart = ['morning', 'afternoon', 'evening'].indexOf(String(p.day_part ?? '')) !== -1 ? p.day_part : null;
  slots.time = Object.assign({}, slots.time, {
    window_from: winMatch[1], window_to: winMatch[2] || winMatch[1], day_part: dayPart,
    window_label: winMatch[1] + (winMatch[2] ? ' .. ' + winMatch[2] : '') + (dayPart ? ' (' + dayPart + ')' : ''),
    source: 'model_extracted', verified_turn: turn
  });
}
// offered slots persist so "the 10am one" still resolves next turn
if (!blocked && evidence.slots.length) slots.time = Object.assign({}, slots.time, { offered: evidence.slots.slice(0, 6) });
if (!blocked && chosenSlot) slots.time = Object.assign({}, slots.time, { chosen_slot: chosenSlot, verified_turn: turn });

// promotion + quote are derived, never asked
if (!blocked && slots.service && slots.service.id) {
  const promo = pool.promotions.find(r => {
    try { const e = JSON.parse(r.eligibility || '{}'); return !e.service_ids || e.service_ids.indexOf(slots.service.id) !== -1; }
    catch { return true; }
  });
  if (promo) slots.promotion = { id: promo.promotion_id, title: promo.title, title_zh: promo.title_zh, discount: promo.discount, verified_turn: turn };
  const listPrice = Number(slots.service.price);
  let disc = 0;
  if (slots.promotion) {
    try {
      const d = typeof slots.promotion.discount === 'string' ? JSON.parse(slots.promotion.discount) : slots.promotion.discount;
      if (d && d.type === 'percent') disc = listPrice * Number(d.value) / 100;
      else if (d && d.type === 'amount') disc = Math.min(listPrice, Number(d.value));
    } catch { disc = 0; }
  }
  if (Number.isFinite(listPrice)) slots.quote = { list_price: listPrice, discount: Math.round(disc * 100) / 100,
    total: Math.round((listPrice - disc) * 100) / 100, currency: slots.service.currency || 'AUD', computed_turn: turn };
}

// ---------------------------------------------------------------------------
// 5. Gaps and the next question (deterministic, never the model's choice)
// ---------------------------------------------------------------------------
const missing = missingSlots(slots);
const toAsk = slotsToAsk(missing);
const ready = missing.length === 0;

// ---------------------------------------------------------------------------
// 6. Render
// ---------------------------------------------------------------------------
let reason = p.escalate === true ? 'agent_escalation' : (errors.length ? 'guardrail_blocked' : 'answered');
if (toolFailures.length && reason === 'answered') reason = 'tool_failure';
const escalate = p.escalate === true || errors.length > 0 || toolFailures.length > 0;
const hitBooking = errors.length === 0 && toolFailures.length === 0 && p.intent === 'booking' && notConfigured.length > 0;
const hitProfile = errors.length === 0 && toolFailures.length === 0 && p.intent === 'profile';
const substantive = ['catalog', 'promotions', 'style', 'stylist', 'booking'].indexOf(p.intent) !== -1;
const escalateGeneric = errors.length > 0 || toolFailures.length > 0 || (p.escalate === true && !substantive);

const priceRows = pool.services.filter(r => (Array.isArray(p.service_ids) ? p.service_ids : []).indexOf(r.service_id) !== -1);
const priceLines = priceRows.map(r => safe(zh ? (r.name_zh || r.name) : r.name) + ' - ' + safe(r.currency || 'AUD', 8) + ' ' + money(r.price) + ' / ' + Number(r.duration_min) + (zh ? ' 分钟' : ' minutes')).join('\n');
const styleRow = p.taxonomy_id ? pool.styles.find(r => r.taxonomy_id === p.taxonomy_id) : null;
const styleProposed = styleRow && paraphrased.styles.has(styleRow.taxonomy_id);
const styleLine = styleRow
  ? (zh ? '匹配的发型：' : 'Matched hairstyle: ') + safe(zh ? (styleRow.name_zh || styleRow.name_en) : (styleRow.name_en || styleRow.name_zh)) +
    (zh ? '。请确认这是否是您想要的。' : '. Please confirm this is what you mean.')
  : '';

// --- answer block ---
let answer = '';
if (escalateGeneric) {
  answer = zh ? '这个问题我帮你转给店里的同事，他们会尽快回复你。' : "I've passed this to a colleague at the salon — they'll get back to you shortly.";
} else if (hitBooking) {
  answer = zh ? '我可以帮你查可约的时段，但最后的锁定要由店员完成。'
              : 'I can look up open times for you, but a staff member has to lock the booking in.';
  reason = 'booking_setup_required';
} else if (hitProfile) {
  answer = zh ? '发质档案需要你自己描述（发丝形态、密度、染烫史），确认后才会保存。目前还没有保存任何资料。'
              : 'A hair profile is self-reported (texture, density, colour history) and is only saved after you confirm. Nothing has been saved.';
  reason = 'profile_setup_required';
} else if (p.intent === 'catalog') {
  const menu = pool.services.slice(0, 6).map(r => safe(zh ? (r.name_zh || r.name) : r.name, 40)).join(zh ? '、' : ', ');
  answer = priceLines || (pool.services.length > 0
    ? (zh ? '这项服务不在本店的服务清单内。可提供的项目：' + menu + (pool.services.length > 6 ? ' 等' : '') + '。'
          : 'That service is not on our menu. What we do offer: ' + menu + (pool.services.length > 6 ? ', and more' : '') + '.')
    : (zh ? '尚无已核实的服务价格，请让店员提供价目表。' : 'No verified service prices are configured yet.'));
} else if (p.intent === 'promotions') {
  const rows = pool.promotions.filter(r => (p.promotion_ids ?? []).indexOf(r.promotion_id) !== -1);
  answer = rows.length
    ? rows.map(r => safe(zh ? (r.title_zh || r.title) : r.title)).join('\n')
    : (zh ? '当前没有可核实且适用的促销。' : 'There are currently no verified eligible promotions.');
} else if (p.intent === 'style') {
  answer = styleLine || (zh ? '想剪成什么长度？到下巴、到肩膀，还是更长？' : 'What length are you after — chin, shoulder, or longer?');
} else if (p.intent === 'stylist') {
  const rows = pool.stylists.filter(r => (p.stylist_ids ?? []).indexOf(r.stylist_id) !== -1);
  const labels = { style_specialty: zh ? '发型专长' : 'style specialty',
    texture_experience: zh ? '自报发质经验' : 'experience with your texture', language_match: zh ? '语言匹配' : 'language match' };
  answer = rows.length
    ? rows.map(r => safe(r.name, 80) + ' — ' + (r.reasons ?? []).map(k => labels[k] || k).join(', ')).join('\n')
    : (zh ? '没有符合条件的发型师。可以放宽语言或价位条件再试。' : 'No matching stylists. You can relax language or price-tier preferences and try again.');
} else {
  answer = '';
}
if (!escalateGeneric && p.intent !== 'style' && styleLine) answer = styleLine + (answer ? '\n' + answer : '');
if (!escalateGeneric && p.intent !== 'catalog' && priceLines) answer = priceLines + (answer ? '\n' + answer : '');

// --- slot block: real, unreserved times ---
let slotBlock = '';
const showSlots = !escalateGeneric && evidence.slots.length > 0 && !ready;
if (showSlots) {
  slotBlock = (zh ? '可约时段（尚未锁定）：\n' : 'Open times (not held yet):\n') +
    evidence.slots.slice(0, 5).map((s, i) => '  ' + (i + 1) + '. ' + safe(s.label, 60) + ' — ' + safe(s.stylist_name, 40)).join('\n');
}

// --- progress block ---
const known = slotLines(slots, zh);
const progress = (!escalateGeneric && known.length >= 2 && !ready)
  ? (zh ? '已确认：' : 'So far: ') + known.join(zh ? ' · ' : ' · ')
  : '';

// --- question / summary block ---
let question = '';
if (escalateGeneric) {
  question = '';
} else if (ready) {
  const q = slots.quote;
  const lines = [zh ? '都齐了，帮你核对一下：' : "That's everything — let me confirm:"];
  for (const l of known) lines.push('  · ' + l);
  if (q) {
    lines.push('  · ' + (zh ? '价格：' : 'Price: ') + q.currency + ' ' + money(q.total) +
      (q.discount > 0 ? (zh ? '（原价 ' : ' (was ') + q.currency + ' ' + money(q.list_price) + (zh ? '，已含' : ', includes ') + safe(zh ? (slots.promotion.title_zh || slots.promotion.title) : slots.promotion.title, 60) + (zh ? '）' : ')') : ''));
  }
  lines.push(zh ? '这个时段还没有锁定——确认后我转给店员帮你正式预约。没问题吗？'
                : "This time is not held yet — confirm and I'll pass it to a staff member to book it in. Does that work?");
  question = lines.join('\n');
} else {
  const asks = {
    service:     zh ? '你想做哪项服务？' : 'Which service would you like?',
    style:       zh ? '想要什么发型？' : 'What hairstyle are you after?',
    time_window: zh ? '什么时候方便？（哪天、上午还是下午）' : 'When suits you — which day, and morning or afternoon?',
    stylist:     zh ? '有指定的发型师吗？没有的话我可以推荐。' : 'Any stylist in particular? I can recommend one if not.',
    time_slot:   zh ? '上面哪个时段合适？' : 'Which of those times works for you?'
  };
  question = toAsk.map(k => asks[k]).filter(Boolean).join(zh ? '\n' : '\n');
}

const blocks = [answer, slotBlock, progress, question].filter(b => b && b.trim());
let reply = blocks.join('\n\n');
if (ctx.truncated) reply += zh ? '\n（你的消息太长被截断了，必要的话再发一次重点。）' : '\n(Your message was truncated — resend the key part if needed.)';

// ---------------------------------------------------------------------------
// 7. Output
// ---------------------------------------------------------------------------
const autoSent = !escalateGeneric;
const nextStatus = escalateGeneric ? 'escalated' : (ready ? 'ready' : 'gathering');
const hallucinationBlocked = errors.filter(e => e.indexOf('unsupported_') === 0).length;
const recent = (Array.isArray(conv.recentTurns) ? conv.recentTurns : []).concat([String(ctx.chatInput || '')]).slice(-3);

return [{ json: {
  session_id: ctx.sessionId,
  request_text: ctx.chatInput,
  draft_reply: reply,
  reason,
  status: autoSent ? 'answered' : 'pending_human',
  guardrail_pass: errors.length === 0,
  errors,
  requires_human: !autoSent,
  auto_sent: autoSent,
  tool_calls: toolCalls,
  not_configured_tools: notConfigured,
  truncated: !!ctx.truncated,
  // state to persist
  slots_next: blocked ? prior : slots,
  slots_json: JSON.stringify(blocked ? prior : slots),
  recent_turns_json: JSON.stringify(recent),
  last_question: toAsk.join(','),
  conv_status: nextStatus,
  turn_count: turn,
  missing: missing,
  proposals,
  ready,
  metrics: {
    guardrail_pass: errors.length === 0 ? 1 : 0,
    errors_count: errors.length,
    hallucination_blocked: hallucinationBlocked,
    tool_call_count: toolCalls.length,
    escalated: escalate ? 1 : 0,
    agent_failed: raw.error ? 1 : 0,
    tool_failures: toolFailures.length,
    not_configured_hit: notConfigured.length ? 1 : 0,
    slots_filled: SLOT_ORDER.length - missing.length,
    turn: turn,
    ready: ready ? 1 : 0
  },
  output: reply
} }];

// Customer-facing reply. The audit row id is NOT shown to the customer; it is
// returned as a sibling field for the test harness and for staff tooling.
const draft   = $('Draft ready').first().json;
const written = $input.first().json;
const zh = draft && /[㐀-鿿]/.test(String(draft.request_text ?? ''));
const logged = !!(written && !written.error && written.id);
let output = String(draft.output ?? '');

// If the audit write failed on a turn that needs a human, the customer would be
// waiting on a request nobody can see. Say so rather than promising follow-up.
if (!logged && draft.requires_human) {
  output += zh ? '\n（系统没能记录这条请求，麻烦你直接联系门店。）'
               : "\n(We couldn't log this request — please contact the salon directly.)";
}

return [{ json: {
  output,
  auto_sent: !!draft.auto_sent,
  requires_human: !!draft.requires_human,
  reason: draft.reason,
  guardrail_pass: draft.guardrail_pass,
  conv_status: draft.conv_status,
  ready: !!draft.ready,
  missing: draft.missing,
  slots: draft.slots_next,
  metrics: draft.metrics,
  logged,
  audit_id: logged ? written.id : null
} }];
